using System;using System.Collections.Generic;using System.Windows.Forms;
namespace LoopFive {
 public class KeyboardCommand {
  public string Id,Name,Group;
  public KeyboardCommand(string id,string name,string group){Id=id;Name=name;Group=group;}
 }
 public static class KeyboardCatalog {
  public static readonly List<KeyboardCommand> Commands=Create();
  static List<KeyboardCommand> Create(){List<KeyboardCommand> a=new List<KeyboardCommand>();string[] track={"cycle|REC / PLAY / OVERDUB (botón circular)","play|Reproducir","dub|Iniciar / terminar sobregrabación","stop|Detener","panic|Detener inmediatamente","undo|Deshacer","redo|Rehacer","mark|Guardar punto MARK","markback|Volver a MARK","clear|Borrar audio (recuperable con Undo)","mute|Silenciar / activar","solo|Solo ON / OFF","reverse|Reversa ON / OFF","oneshot|One Shot ON / OFF","fx|Efectos ON / OFF","levelup|Subir volumen 5%","leveldown|Bajar volumen 5%","panleft|Panorama hacia izquierda","panright|Panorama hacia derecha","pancenter|Centrar panorama","speed|Cambiar velocidad HALF / NORMAL / DOUBLE","loopsync|Loop Sync ON / OFF","temposync|Tempo Sync ON / OFF","tempomode|Tempo PITCH / XFADE","fadein|Fundido de entrada ON / OFF","stopmode|Parada inmediata / fundido / fin de loop","dubmode|Overdub / Replace 1 / Replace 2","inputl|Grabar entrada L ON / OFF","inputr|Grabar entrada R ON / OFF","rhythm|Grabar ritmo ON / OFF","allstart|Incluir en inicio global ON / OFF","allstop|Incluir en parada global ON / OFF","measureup|Aumentar duración fija (compases)","measuredown|Reducir duración fija / AUTO / libre"};
   for(int t=-1;t<5;t++){string group=t<0?"Pista seleccionada":"Pista "+(t+1),prefix=t<0?"selected.":"track."+t+".";foreach(string item in track){string[] p=item.Split('|');a.Add(new KeyboardCommand(prefix+p[0],group+" · "+p[1],group));}}
   Add(a,"Global","global.",new string[]{"direct|Activar inicio inmediato al pulsar","start|Reproducir todas","stop|Detener todas","panic|Parada inmediata de todas","reset|Reiniciar transporte","tap|Tap tempo","tempoup|Subir tempo 1 BPM","tempodown|Bajar tempo 1 BPM","masterup|Subir volumen máster 5%","masterdown|Bajar volumen máster 5%","inputup|Subir ganancia de entrada 10%","inputdown|Bajar ganancia de entrada 10%","inputmute|Silenciar entrada ON / OFF","monitor|Monitor de entrada ON / OFF","compressor|Compresor de entrada ON / OFF","limiter|Limitador ON / OFF","mastercompressor|Compresor máster ON / OFF","reverbup|Subir reverb máster 5%","reverbdown|Bajar reverb máster 5%","quantize|Cuantización ON / OFF","autorec|Auto Record ON / OFF","autotempo|Auto Tempo ON / OFF","single|Reproducción SINGLE / MULTI","recdub|Orden REC→PLAY / REC→DUB","countin|Cambiar cuenta previa 0–4 compases","synclength|Sincronizar global / compás / longitud de loop"});
   Add(a,"Ritmo","rhythm.",new string[]{"toggle|Iniciar / detener ritmo","start|Iniciar ritmo","stop|Detener ritmo","fill|Solicitar fill","ending|Solicitar ending","intro|Intro ON / OFF","variationnext|Siguiente variación","patternnext|Siguiente patrón","patternprev|Patrón anterior","kitnext|Siguiente kit","kitprev|Kit anterior","levelup|Subir volumen de ritmo 5%","leveldown|Bajar volumen de ritmo 5%","swingup|Aumentar swing 5%","swingdown|Reducir swing 5%"});for(int i=0;i<4;i++)a.Add(new KeyboardCommand("rhythm.variation."+i,"Variación "+(char)('A'+i),"Ritmo"));for(int i=0;i<8;i++)a.Add(new KeyboardCommand("rhythm.pad."+i,"Pad · "+RhythmEngine.Instruments[i],"Ritmo"));
   foreach(string section in new string[]{"input","track"}){string group=section=="input"?"Input FX":"Track FX",prefix="fx."+section+".";Add(a,group,prefix,new string[]{"enable|Cadena ON / OFF","single|FX SINGLE / MULTI","banknext|Siguiente banco","bankprev|Banco anterior"});for(int b=0;b<4;b++)a.Add(new KeyboardCommand(prefix+"bank."+b,group+" · Banco "+(char)('A'+b),group));for(int s=0;s<4;s++){string p=prefix+"slot."+s+".",name=group+" · FX "+(char)('A'+s)+" · ";foreach(string item in new string[]{"toggle|Activar / desactivar","hold|Mantener mientras se pulsa","on|Activar","off|Desactivar","typenext|Siguiente tipo","typeprev|Tipo anterior","amountup|Subir Amount 5%","amountdown|Bajar Amount 5%","rateup|Subir velocidad / tiempo 5%","ratedown|Bajar velocidad / tiempo 5%","mixup|Subir mezcla 5%","mixdown|Bajar mezcla 5%","feedbackup|Subir feedback 5%","feedbackdown|Bajar feedback 5%","sync|Sincronía de tempo ON / OFF","sequence|Secuencia ON / OFF","retrigger|Retrigger de secuencia ON / OFF"}){string[] z=item.Split('|');a.Add(new KeyboardCommand(p+z[0],name+z[1],group));}}
    for(int b=0;b<4;b++)for(int s=0;s<4;s++){a.Add(new KeyboardCommand(prefix+"direct."+b+"."+s+".toggle",group+" · Banco "+(char)('A'+b)+" / FX "+(char)('A'+s)+" · Activar / desactivar",group));a.Add(new KeyboardCommand(prefix+"direct."+b+"."+s+".hold",group+" · Banco "+(char)('A'+b)+" / FX "+(char)('A'+s)+" · Mantener",group));}}
   Add(a,"Programa / memorias","app.",new string[]{"save|Guardar sesión","saveas|Guardar sesión como…","open|Abrir sesión","exportmix|Exportar mezcla","masterrecord|Iniciar / terminar grabación máster","memorynext|Seleccionar memoria siguiente","memoryprev|Seleccionar memoria anterior","memoryrecall|Recuperar memoria seleccionada","memorywrite|Escribir memoria seleccionada","keyboard|Abrir Opciones → Teclado","help|Abrir ayuda","performance|Mostrar pistas","rhythmpage|Mostrar ritmos","fxpage|Mostrar efectos","trackedit|Editar pista seleccionada","trackimport|Importar WAV a pista seleccionada","trackexport|Exportar WAV de pista seleccionada"});for(int i=0;i<5;i++)a.Add(new KeyboardCommand("app.select."+i,"Seleccionar pista "+(i+1),"Programa / memorias"));return a;
  }
  static void Add(List<KeyboardCommand> a,string group,string prefix,string[] items){foreach(string item in items){string[] p=item.Split('|');a.Add(new KeyboardCommand(prefix+p[0],p[1],group));}}
  public static KeyboardCommand Find(string id){return Commands.Find(delegate(KeyboardCommand c){return c.Id==id;});}
  public static string KeyName(int value){if(value==0)return "Sin asignar";Keys k=(Keys)value;string text="";if((k&Keys.Control)!=0)text+="Ctrl + ";if((k&Keys.Alt)!=0)text+="Alt + ";if((k&Keys.Shift)!=0)text+="Shift + ";Keys code=k&Keys.KeyCode;string name=code>=Keys.D0&&code<=Keys.D9?((int)(code-Keys.D0)).ToString():code==Keys.Space?"Espacio":code==Keys.Escape?"Esc":code==Keys.Oemplus?"+":code==Keys.OemMinus?"-":code.ToString();return text+name;}
  public static string InvalidKey(Keys k){Keys code=k&Keys.KeyCode;if(code==Keys.None||code==Keys.ShiftKey||code==Keys.ControlKey||code==Keys.Menu||code==Keys.LShiftKey||code==Keys.RShiftKey||code==Keys.LControlKey||code==Keys.RControlKey||code==Keys.LMenu||code==Keys.RMenu)return "Pulsa una tecla además de los modificadores.";if(!Enum.IsDefined(typeof(Keys),code)||((int)k&~(int)(Keys.KeyCode|Keys.Control|Keys.Shift|Keys.Alt))!=0)return "Tecla no válida.";if(code==Keys.LWin||code==Keys.RWin||(k&Keys.Alt)!=0&&(code==Keys.F4||code==Keys.Tab||code==Keys.Escape)||(k&Keys.Control)!=0&&code==Keys.Escape||(k&(Keys.Control|Keys.Alt))==(Keys.Control|Keys.Alt)&&code==Keys.Delete)return "Esa combinación está reservada por Windows.";return null;}
  public static void Validate(List<KeyBinding> bindings){if(bindings==null||bindings.Count>Commands.Count)throw new Exception("Perfil de teclado incompleto o demasiado grande.");HashSet<int> keys=new HashSet<int>();HashSet<string> ids=new HashSet<string>();foreach(KeyBinding b in bindings){if(b==null||Find(b.Action)==null||!ids.Add(b.Action))throw new Exception("El perfil contiene funciones desconocidas o repetidas.");string error=InvalidKey((Keys)b.Key);if(error!=null)throw new Exception(error);if(!keys.Add(b.Key))throw new Exception("Tecla repetida en el perfil: "+KeyName(b.Key));}}
 }
 public class KeyboardController {
  Engine engine;Action<string> host;Dictionary<Keys,Action> held=new Dictionary<Keys,Action>();
  public KeyboardController(Engine e,Action<string> ui){engine=e;host=ui;KeyDefaults.Ensure(e.System);}
  public bool Down(Keys chord){Keys code=chord&Keys.KeyCode;if(held.ContainsKey(code))return true;if(!engine.System.KeyboardEnabled)return false;KeyBinding binding=engine.System.KeyboardBindings.Find(delegate(KeyBinding b){return b!=null&&b.Key==(int)chord;});if(binding==null||KeyboardCatalog.Find(binding.Action)==null)return false;held[code]=null;try{Action release=Execute(binding.Action);if(held.ContainsKey(code))held[code]=release;else if(release!=null)release();}catch{held.Remove(code);throw;}return true;}
  public bool Up(Keys key){Keys code=key&Keys.KeyCode;Action release;if(!held.TryGetValue(code,out release))return false;held.Remove(code);if(release!=null)release();return true;}
  public void ReleaseAll(){List<Action> releases=new List<Action>(held.Values);held.Clear();foreach(Action release in releases)if(release!=null)release();}
  public Action Execute(string id){if(id.StartsWith("app.")||id=="global.tap"||id=="global.start"||id=="global.stop"||id=="global.panic"){if(host!=null)host(id);return null;}lock(engine.Gate){SessionConfig c=engine.Config;
   if(id.StartsWith("track.")||id.StartsWith("selected.")){string[] p=id.Split('.');int i=p[0]=="selected"?c.SelectedTrack:int.Parse(p[1]);string op=p[p.Length-1];Track t=engine.Tracks[i];TrackConfig tc=t.Config;c.SelectedTrack=i;
    switch(op){case "cycle":engine.Action(i);break;case "play":engine.Play(i);break;case "dub":engine.Overdub(i);break;case "stop":engine.Stop(i,false);break;case "panic":engine.Stop(i,true);break;case "undo":engine.Undo(i,false);break;case "redo":engine.Undo(i,true);break;case "mark":engine.Mark(i,false);break;case "markback":engine.Mark(i,true);break;case "clear":engine.Clear(i);break;case "mute":tc.Mute=!tc.Mute;break;case "solo":tc.Solo=!tc.Solo;break;case "reverse":tc.Reverse=!tc.Reverse;break;case "oneshot":tc.OneShot=!tc.OneShot;break;case "fx":tc.Effects=!tc.Effects;break;case "levelup":tc.Level=Math.Min(2,tc.Level+.05f);break;case "leveldown":tc.Level=Math.Max(0,tc.Level-.05f);break;case "panleft":tc.Pan=Math.Max(-1,tc.Pan-.1f);break;case "panright":tc.Pan=Math.Min(1,tc.Pan+.1f);break;case "pancenter":tc.Pan=0;break;case "speed":tc.Speed=tc.Speed<.75f?1:tc.Speed<1.5f?2:.5f;break;case "loopsync":tc.LoopSync=!tc.LoopSync;break;case "temposync":tc.TempoSync=!tc.TempoSync;break;case "tempomode":tc.TempoMode=1-tc.TempoMode;break;case "fadein":tc.FadeIn=!tc.FadeIn;break;case "stopmode":tc.StopMode=(tc.StopMode+1)%3;break;case "dubmode":tc.DubMode=(tc.DubMode+1)%3;break;case "inputl":tc.InputL=!tc.InputL;break;case "inputr":tc.InputR=!tc.InputR;break;case "rhythm":tc.RecordRhythm=!tc.RecordRhythm;break;case "allstart":tc.AllStart=!tc.AllStart;break;case "allstop":tc.AllStop=!tc.AllStop;break;case "measureup":tc.MeasureBeats=0;tc.Measures=tc.Measures<1?1:Math.Min(128,tc.Measures*2);break;case "measuredown":tc.MeasureBeats=0;tc.Measures=tc.Measures>1?tc.Measures/2:tc.Measures==1?0:-1;break;default:throw new Exception("Control de pista desconocido.");}engine.Dirty=true;return null;
   }
   if(id.StartsWith("fx.")){string[] p=id.Split('.');bool input=p[1]=="input";ChainConfig chain=input?c.InputFx:c.TrackFx;string op=p[p.Length-1];if(p[2]=="bank"){chain.Bank=int.Parse(p[3]);engine.Dirty=true;return null;}if(p[2]!="slot"&&p[2]!="direct"){if(op=="enable")chain.Enabled=!chain.Enabled;else if(op=="single"){chain.Single=!chain.Single;if(chain.Single){bool found=false;for(int j=0;j<4;j++){FxConfig slot=chain.Slots[chain.Bank*4+j];if(slot.On){if(found)slot.On=false;found=true;}}}}else if(op=="banknext")chain.Bank=(chain.Bank+1)%4;else if(op=="bankprev")chain.Bank=(chain.Bank+3)%4;else throw new Exception("Control FX desconocido.");engine.Dirty=true;return null;}
    int bank=p[2]=="direct"?int.Parse(p[3]):chain.Bank,slotIndex=int.Parse(p[p[2]=="direct"?4:3]);FxConfig fx=chain.Slots[bank*4+slotIndex];bool previous=fx.On;
    if(op=="toggle"||op=="hold"||op=="on"){bool on=op!="toggle"||fx.Momentary||!fx.On;if(on&&chain.Single)for(int j=0;j<4;j++)chain.Slots[bank*4+j].On=false;fx.On=on;engine.Dirty=true;if(op=="hold"||op=="toggle"&&fx.Momentary)return delegate{lock(engine.Gate){fx.On=op=="hold"?previous:false;engine.Dirty=true;}};return null;}
    switch(op){case "off":fx.On=false;break;case "typenext":case "typeprev":string[] types=input?FxCatalog.Input:FxCatalog.All;int ix=Array.IndexOf(types,fx.Type);fx.Type=types[(ix+types.Length+(op=="typenext"?1:-1))%types.Length];break;case "amountup":fx.Amount=Math.Min(1,fx.Amount+.05f);break;case "amountdown":fx.Amount=Math.Max(0,fx.Amount-.05f);break;case "rateup":fx.Rate=Math.Min(1,fx.Rate+.05f);break;case "ratedown":fx.Rate=Math.Max(0,fx.Rate-.05f);break;case "mixup":fx.Mix=Math.Min(1,fx.Mix+.05f);break;case "mixdown":fx.Mix=Math.Max(0,fx.Mix-.05f);break;case "feedbackup":fx.Feedback=Math.Min(.94f,fx.Feedback+.05f);break;case "feedbackdown":fx.Feedback=Math.Max(0,fx.Feedback-.05f);break;case "sync":fx.Sync=!fx.Sync;break;case "sequence":fx.Sequence=!fx.Sequence;break;case "retrigger":fx.SequenceRetrigger=!fx.SequenceRetrigger;break;default:throw new Exception("Parámetro FX desconocido.");}engine.Dirty=true;return null;
   }
   if(id.StartsWith("rhythm.")){RhythmConfig r=c.Rhythm;string[] p=id.Split('.');string op=p[1];int next=-1;if(op=="pad"){engine.Drums.Hit(int.Parse(p[2]),1);return null;}switch(op){case "toggle":r.Enabled=!r.Enabled;break;case "start":r.Enabled=true;break;case "stop":r.Enabled=false;break;case "fill":r.Fill=true;break;case "ending":r.Ending=true;break;case "intro":r.Intro=!r.Intro;break;case "variation":next=int.Parse(p[2]);break;case "variationnext":next=((engine.Drums.PendingVariation>=0?engine.Drums.PendingVariation:r.Variation)+1)%4;break;case "patternnext":r.Pattern=(r.Pattern+1)%211;break;case "patternprev":r.Pattern=(r.Pattern+210)%211;break;case "kitnext":r.Kit=(r.Kit+1)%16;break;case "kitprev":r.Kit=(r.Kit+15)%16;break;case "levelup":r.Level=Math.Min(2,r.Level+.05f);break;case "leveldown":r.Level=Math.Max(0,r.Level-.05f);break;case "swingup":r.Swing=Math.Min(1,r.Swing+.05f);break;case "swingdown":r.Swing=Math.Max(0,r.Swing-.05f);break;default:throw new Exception("Control de ritmo desconocido.");}if(next>=0){if(r.Enabled)engine.Drums.PendingVariation=next;else r.Variation=next;}engine.Dirty=true;return null;}
   switch(id){case "global.direct":engine.SetImmediateRecording();break;case "global.reset":engine.ResetTransport();break;case "global.tempoup":engine.SetTempo(c.Bpm+1);break;case "global.tempodown":engine.SetTempo(c.Bpm-1);break;case "global.masterup":c.Master=Math.Min(2,c.Master+.05f);break;case "global.masterdown":c.Master=Math.Max(0,c.Master-.05f);break;case "global.inputup":c.InputGain=Math.Min(4,c.InputGain+.1f);break;case "global.inputdown":c.InputGain=Math.Max(0,c.InputGain-.1f);break;case "global.inputmute":c.InputMute=!c.InputMute;break;case "global.monitor":c.Monitor=!c.Monitor;break;case "global.compressor":c.InputCompressor=!c.InputCompressor;break;case "global.limiter":c.Limiter=!c.Limiter;break;case "global.mastercompressor":c.MasterCompressor=!c.MasterCompressor;break;case "global.reverbup":c.MasterReverb=Math.Min(1,c.MasterReverb+.05f);break;case "global.reverbdown":c.MasterReverb=Math.Max(0,c.MasterReverb-.05f);break;case "global.quantize":c.Quantize=!c.Quantize;break;case "global.autorec":c.AutoRecord=!c.AutoRecord;break;case "global.autotempo":c.AutoTempo=!c.AutoTempo;break;case "global.single":c.SinglePlay=!c.SinglePlay;break;case "global.recdub":c.RecToDub=!c.RecToDub;break;case "global.countin":c.CountInBars=(c.CountInBars+1)%5;break;case "global.synclength":c.SyncMode=(c.SyncMode+1)%3;break;default:throw new Exception("Función de teclado desconocida: "+id);}engine.Dirty=true;return null;
  }}
 }
}
